selector {
    opacity: 0;
    filter: blur(7px);
    transform: translate(0, 80px);
    animation: showFromBottom 0.5s 3.5s ease forwards;
}

/* Keyframe que anima de "scroll-bottom" para o estado final */
@keyframes showFromBottom {
    from {
        opacity: 0;
        filter: blur(7px);
        transform: translate(0, 80px);
    }
    to {
        opacity: 1;
        filter: blur(0);
        transform: translate(0, 0);
    }
}

