settings.custom_css:
/* CARD */
.card-lista {
  background: #fff;
  border: 0px solid #000;
  transition: background 0.4s ease-in-out;
}

.card-lista:hover {
  background: #EBEBEB!important;
  border: 1px solid #C9E4D2;
}

/* LISTA DE ÍCONES */
.lista .elementor-icon-list-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  cursor: pointer;
}

/* TEXTO */
.lista .elementor-icon-list-text {
  position: relative;
  top: 0px;
  padding: 0;
  margin: 0;
  display: block;
  text-align: left;
}

/* TRACINHO ANIMADO */
.lista .elementor-icon-list-text::after {
  content: "";
  display: block;
  width: 1.91019rem;
  height: 0.23875rem;
  background: #F10505;
  border-radius: 2px;
  margin-top: 11px;
  transition: width 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ÍCONE SVG */
.lista .elementor-icon-list-icon svg path {
  transition: fill 0.4s ease-in-out, fill-opacity 0.4s ease-in-out, opacity 0.4s ease-in-out;
}

/* HOVER GERAL NO CARD */
.card-lista:hover .elementor-icon-list-text::after {
  width: 2.8rem;
}

.card-lista:hover .elementor-icon-list-icon svg path {
  fill: #2D306F;
  fill-opacity: 1 !important;
  opacity: 1 !important;
}

